import XCTest

final class MuteSpammerUITests: XCTestCase {
    let udid = "F7FA1462-2FB0-472C-8A1D-9D3945FD2051"
    let base = "/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode"
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = true
        app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    }

    func shot(_ name: String) {
        let p = Process()
        p.executableURL = URL(fileURLWithPath: "/usr/bin/xcrun")
        p.arguments = ["simctl", "io", udid, "screenshot", "\(base)/step_\(name).png"]
        do { try p.run(); p.waitUntilExit() } catch { print("shot failed: \(error)") }
    }

    func dumpHier(_ name: String) {
        let d = app.debugDescription
        try? d.write(toFile: "\(base)/hier_\(name).txt", atomically: true, encoding: .utf8)
        print("hierarchy written to hier_\(name).txt")
    }

    func testMuteLoudSpammer() throws {
        app.launch()
        XCTAssertTrue(app.staticTexts["Following"].waitForExistence(timeout: 30), "home feed did not load")
        shot("1_home")

        let searchTab = app.buttons["Search"]
        guard searchTab.waitForExistence(timeout: 10) else {
            dumpHier("notab")
            XCTFail("search tab not found")
            return
        }
        searchTab.tap()

        let field = app.textFields.firstMatch
        guard field.waitForExistence(timeout: 10) else {
            dumpHier("nofield")
            XCTFail("search field not found")
            return
        }
        field.tap()
        field.typeText("loudspammer.test")
        shot("2_typed")

        let pred = NSPredicate(format: "label CONTAINS 'loudspammer'")
        let result = app.staticTexts.matching(pred).firstMatch
        guard result.waitForExistence(timeout: 20) else {
            dumpHier("noresult")
            XCTFail("no search result")
            return
        }
        result.tap()

        let postsTab = app.staticTexts["Posts"]
        if !postsTab.waitForExistence(timeout: 10) {
            let again = app.staticTexts.matching(pred).firstMatch
            if again.exists { again.tap() }
            guard postsTab.waitForExistence(timeout: 10) else {
                dumpHier("noprofile")
                XCTFail("profile did not open")
                return
            }
        }
        shot("3_profile")

        var opened = false
        for label in ["Options", "More options", "Menu", "More", "Open menu"] {
            let b = app.buttons[label]
            if b.waitForExistence(timeout: 2) {
                b.tap()
                opened = true
                break
            }
        }
        if !opened {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.93, dy: 0.09)).tap()
        }

        let mutePred = NSPredicate(format: "label CONTAINS 'Mute'")
        let mute = app.staticTexts.matching(mutePred).firstMatch
        guard mute.waitForExistence(timeout: 10) else {
            dumpHier("nomute")
            shot("4_menu_fail")
            XCTFail("mute item not found")
            return
        }
        shot("4_menu")
        mute.tap()
        shot("5_after_mute")

        let muted = app.staticTexts["Muted"]
        if !muted.waitForExistence(timeout: 10) {
            dumpHier("notmuted")
        }
        shot("6_done")
        print("mute flow completed")
    }
}

